Status validate_military_state(const CommonRead& c,const MilitaryState& s,const MilitaryCatalog& cat,const MilitaryAccess& a){return validate_military_state_impl(c,s,cat,a,nullptr,nullptr);}
Status validate_military_state(const CommonStore& c,const MilitaryState& s,const MilitaryCatalog& cat,const MilitaryAccess& a,const ExactMilitaryStateValidationContext& x){
 auto actual=exact_source_context(c,s,cat,a,x);if(!actual.ok)return actual;
 auto original=validate_military_state_impl(c,s,cat,a,&c,&x);if(!original.ok)return original;
 // All retained real periods have complete military coverage, not merely valid
 // individual receipts. An outer stable Open validator also asks for its real
 // current period, including a completely missing first batch.
 std::set<Integer> periods;for(const auto& row:s.supply_facts)periods.insert(row.tick-1);
 for(const auto from:periods){if(x.field_supply_source1){if(x.dynamic_military)return common_failure("FieldMilitarySupplySelectionMismatch");auto now=x.clock.read_current_moment();if(!now.ok)return {false,{},now.error};auto supplies=read_field_military_supply_opening_sources(c,s,cat,a,x.periods,x.formations,from,now.value,x.budget,x.returns);if(!supplies.ok)return {false,{},supplies.error};continue;}if(!x.dynamic_military)return common_failure("MilitarySupplyPeriodSourceRequired");auto now=x.clock.read_current_moment();if(!now.ok)return {false,{},now.error};auto supplies=read_exact_military_supply_opening_sources(c,s,*x.dynamic_military,cat,a,x.periods,x.formations,from,now.value,x.budget,x.returns);if(!supplies.ok)return {false,{},supplies.error};}
 return common_success();
}
